APX.mx = {"country":{"name":"Mexico","tagline":"The oldest winery in the Americas, a desert valley that became a culinary capital, and vineyards two kilometres up on the tropic's edge.","classification":"Mexico has no national appellation system comparable to the AOC or AVA. Labels typically give the state and valley informally (Valle de Guadalupe, Valle de Parras). In 2025 the Instituto Mexicano de la Propiedad Industrial (IMPI) granted the first protected geographical indication (IGP) for wine, for the Querétaro wine region; Baja California's Comité Provino began an IGP process with El Colegio de la Frontera Norte in December 2025, and Coahuila producers are pursuing one. Wine policy is coordinated by the Consejo Mexicano Vitivinícola. Mexico imposes high excise taxes on wine, which weighs on prices."},"regions":[{"name":"Baja California","slug":"baja-california","tagline":"Desert valleys behind Ensenada where Pacific fog, granite and Mediterranean grapes made Mexico's wine country.","ids":["mx-san-antonio-de-las-minas","mx-valle-de-guadalupe","mx-valle-de-ojos-negros","mx-valle-de-san-vicente","mx-valle-de-santo-tomas","mx-valle-de-tecate","mx-valle-de-la-grulla"]},{"name":"Coahuila","slug":"coahuila","tagline":"A spring-fed oasis in the Chihuahuan Desert where the oldest winery in the Americas still makes wine.","ids":["mx-sierra-de-arteaga","mx-valle-de-parras"]},{"name":"Querétaro","slug":"queretaro","tagline":"Sparkling wine and fresh whites at 2,000 m, holder of Mexico's first wine IGP.","ids":["mx-queretaro"]},{"name":"Central Highlands (Bajío and Altiplano)","slug":"central-highlands-baj-o-and-altiplano","tagline":"Tropic-edge vineyards at altitude, from Hidalgo's Dolores to the brandy grapes of Zacatecas.","ids":["mx-aguascalientes","mx-guanajuato","mx-san-luis-potosi","mx-zacatecas"]},{"name":"Northern Mexico (Chihuahua and Sonora)","slug":"northern-mexico-chihuahua-and-sonora","tagline":"Desert irrigation and Jesuit mission vines: brandy, table grapes and a new wine scene.","ids":["mx-chihuahua","mx-sonora"]}],"items":{"mx-aguascalientes":{"name":"Aguascalientes","cat":"Region","region":"Central Highlands (Bajío and Altiplano)","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Merlot, Chenin Blanc","summary":"A central state at about 1,900 m with a long grape tradition: brandy houses and a famous grape harvest fair (Feria de la Uva) in the 20th century, and 6,715 t of industrial grapes in 2025. Modern wineries include Vinícola Santa Elena and Hacienda de Letras.","producers":["Vinícola Santa Elena","Hacienda de Letras"],"rslug":"central-highlands-baj-o-and-altiplano"},"mx-chihuahua":{"name":"Chihuahua","cat":"Region","region":"Northern Mexico (Chihuahua and Sonora)","styles":["red","white"],"grapes":"Cabernet Sauvignon, Merlot, Tempranillo, Chenin Blanc","summary":"Northern state with wineries around Delicias, Encinillas and Casas Grandes at high elevation, and mission vines at Cerocahui in the Copper Canyon, planted by Jesuits.","rslug":"northern-mexico-chihuahua-and-sonora"},"mx-guanajuato":{"name":"Guanajuato","cat":"Region","region":"Central Highlands (Bajío and Altiplano)","styles":["red","white"],"grapes":"Cabernet Sauvignon, Syrah, Merlot, Cabernet Franc, Tempranillo, Malbec, Sauvignon Blanc","summary":"Guanajuato's vineyards lie around Dolores Hidalgo and San Miguel de Allende at about 1,900 to 2,100 m. Father Miguel Hidalgo taught his parishioners at Dolores to grow vines before the 1810 War of Independence, and the viceroyalty had them destroyed; the area's modern wine revival began in the 2000s with Cuna de Tierra and now includes estates around San Miguel such as Dos Búhos and San Lucas.","producers":["Cuna de Tierra","Dos Búhos","Viñedo San Lucas","Tres Raíces"],"rslug":"central-highlands-baj-o-and-altiplano"},"mx-queretaro":{"name":"Querétaro","cat":"IG","region":"Querétaro","created":"2025","styles":["sparkling","white","red","rose"],"grapes":"Sauvignon Blanc, Chardonnay, Macabeo, Xarel-lo, Parellada, Pinot Noir, Malbec, Tempranillo, Cabernet Sauvignon","summary":"Mexico's first protected geographical indication for wine, granted by IMPI and launched in April 2025, covering the wine region of Querétaro state. Vineyards sit around Ezequiel Montes, Tequisquiapan, Colón and Cadereyta at about 1,800 to 2,100 m, among the highest in North America. Days are warm, nights cold and summer rain coincides with ripening, so grapes keep high acidity and moderate sugar: ideal for traditional-method sparkling wine, which is the region's speciality. Freixenet de México at Ezequiel Montes, with deep underground cellars, has made traditional-method sparkling wine here since the 1980s; La Redonda, Viñedos Azteca, De Cote and Puerta del Lobo make still wines.","producers":["Freixenet de México (Finca Sala Vivé)","La Redonda","Viñedos Azteca","Bodegas De Cote","Puerta del Lobo"],"rslug":"queretaro"},"mx-san-antonio-de-las-minas":{"name":"San Antonio de las Minas","cat":"Region","region":"Baja California","subregion":"Valle de Guadalupe area","styles":["red","white"],"grapes":"Tempranillo, Cabernet Sauvignon, Chardonnay","summary":"A small valley just south of Valle de Guadalupe, on the road to Ensenada, where Hugo D'Acosta founded Casa de Piedra in 1997 and the teaching winery La Escuelita. Slightly cooler and more exposed to marine air than Guadalupe.","producers":["Casa de Piedra","Villa Montefiori","Paralelo"],"rslug":"baja-california"},"mx-san-luis-potosi":{"name":"San Luis Potosí","cat":"Region","region":"Central Highlands (Bajío and Altiplano)","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Merlot","summary":"A high-desert state on the Altiplano with a small but growing number of wineries, part of the central highland expansion, at about 1,800 to 2,000 m. Like its neighbours, it relies on altitude for cool nights and battles summer rain and hail.","rslug":"central-highlands-baj-o-and-altiplano"},"mx-sierra-de-arteaga":{"name":"Sierra de Arteaga","cat":"Region","region":"Coahuila","styles":["red","white"],"grapes":"Pinot Noir, Chardonnay, Cabernet Sauvignon","summary":"A cooler, higher wine area (around 2,000 m) in the mountains east of Saltillo, near the town of Arteaga, with apple orchards and new boutique wineries.","producers":["Bodega Los Cedros","Bodegas del Viento"],"rslug":"coahuila"},"mx-sonora":{"name":"Sonora","cat":"Region","region":"Northern Mexico (Chihuahua and Sonora)","styles":["red","white"],"grapes":"Table and brandy grapes, Cabernet Sauvignon","summary":"Mexico's largest grape-growing state, but mostly for export table grapes and for brandy, in irrigated desert around Hermosillo and Caborca. Wine production is small, though a few wineries have appeared, and the Jesuit missions of the Pimería Alta once grew vines here.","rslug":"northern-mexico-chihuahua-and-sonora"},"mx-valle-de-guadalupe":{"name":"Valle de Guadalupe","cat":"Region","region":"Baja California","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Nebbiolo, Merlot, Syrah, Grenache, Zinfandel, Chenin Blanc","summary":"Mexico's most famous wine valley, about 20 km northeast of Ensenada along Highway 3, the Ruta del Vino. Dominicans founded the mission of Nuestra Señora de Guadalupe del Norte here in 1834; Russian Molokan families farmed the valley from 1905 (their museum survives in Francisco Zarco); L.A. Cetto and Domecq industrialised it from the 1970s; and Monte Xanic (1987), Château Camou, Adobe Guadalupe, Casa de Piedra and dozens of boutique wineries turned it into a food-and-wine destination, from 6 wineries in 1999 to about 150 in 2023.\n\nThe climate is Mediterranean, with hot days moderated by Pacific air drawn through the canyon from El Sauzal, and the soils are sandy decomposed granite. Reds dominate: Cabernet Sauvignon, Tempranillo, Nebbiolo, Merlot, Grenache and blends that combine ripe fruit with a saline, slightly bitter edge. Water is the valley's crisis: vineyards draw on an overexploited aquifer, and salinity is rising.","producers":["Monte Xanic","L.A. Cetto","Château Camou","Adobe Guadalupe","Vena Cava","Bruma","Vinícola Torres Alegre","Las Nubes","Hacienda La Lomita"],"rslug":"baja-california"},"mx-valle-de-la-grulla":{"name":"Valle de la Grulla","cat":"Region","region":"Baja California","styles":["red","white"],"grapes":"Grenache, Carignan, Cabernet Sauvignon","summary":"A small valley on the road south of Ensenada around Ejido Uruapan and Santo Tomás, also called Valle de Uruapan, with old Grenache and Carignan vines and a cooler, coastal-influenced climate.","rslug":"baja-california"},"mx-valle-de-ojos-negros":{"name":"Valle de Ojos Negros","cat":"Region","region":"Baja California","styles":["white","red"],"grapes":"Sauvignon Blanc, Chardonnay, Cabernet Sauvignon, Pinot Noir","summary":"A high inland valley east of Ensenada at about 700 m, cooler at night than the coastal valleys, with snow on the surrounding mountains in winter. Monte Xanic and others grow fresh Sauvignon Blanc and Chardonnay and Pinot Noir here.","producers":["Monte Xanic (Ojos Negros vineyards)","Bodegas Henri Lurton"],"rslug":"baja-california"},"mx-valle-de-parras":{"name":"Valle de Parras","cat":"Region","region":"Coahuila","styles":["red","white"],"grapes":"Cabernet Sauvignon, Shiraz, Merlot, Tempranillo, Chardonnay, Chenin Blanc","summary":"A spring-fed valley in the Chihuahuan Desert of southern Coahuila, at about 1,500 m, named for its wild vines. Casa Madero's Hacienda de San Lorenzo (1597) is the oldest winery in the Americas, and several family wineries and brandy distilleries surround the colonial town of Parras de la Fuente. Hot days, cold nights and spring water give structured Cabernet and Shiraz and crisp Chardonnay.","producers":["Casa Madero","Rivero González","Vinícola San Juan de la Vaquería"],"rslug":"coahuila"},"mx-valle-de-san-vicente":{"name":"Valle de San Vicente","cat":"Region","region":"Baja California","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Grenache, Merlot","summary":"A broad valley about 90 km south of Ensenada around San Vicente, with a Dominican mission founded in 1780. Warm and dry, it supplies grapes to many Guadalupe wineries and grows Cabernet, Tempranillo and Grenache.","producers":["Bodegas San Rafael (sourcing)"],"rslug":"baja-california"},"mx-valle-de-santo-tomas":{"name":"Valle de Santo Tomás","cat":"Region","region":"Baja California","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Chenin Blanc, Chardonnay","summary":"A valley about 45 km south of Ensenada, site of the Dominican mission of Santo Tomás de Aquino (1791) and the vineyards of Bodegas de Santo Tomás, Baja California's first commercial winery (1888). Cooler, windier and with heavier soils than Guadalupe.","producers":["Bodegas de Santo Tomás"],"rslug":"baja-california"},"mx-valle-de-tecate":{"name":"Valle de Tecate","cat":"Region","region":"Baja California","styles":["red","white"],"grapes":"Syrah, Cabernet Sauvignon, Nebbiolo","summary":"The northernmost Baja wine area, around the border town of Tecate, at about 500 m. Rancho La Puerta's vineyards and small wineries grow Rhône and Bordeaux varieties.","rslug":"baja-california"},"mx-zacatecas":{"name":"Zacatecas","cat":"Region","region":"Central Highlands (Bajío and Altiplano)","styles":["red","white"],"grapes":"Cabernet Sauvignon, Tempranillo, Merlot, Ruby Cabernet","summary":"A high-plateau state (about 2,000 m) that was Mexico's second-largest wine-grape producer in 2025 (26,024 t), mostly around Ojocaliente and Luis Moya, historically supplying brandy distillers. A handful of wineries now bottle Cabernet, Tempranillo and Merlot.","rslug":"central-highlands-baj-o-and-altiplano"}}};
